import { test, expect } from '@playwright/test';

test.describe('Search Query Saving', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should save a search query', async ({ page }) => {
    await page.getByRole('textbox', { name: 'Search' }).fill('Test Query');
    await page.getByRole('button', { name: 'Search' }).click();
    await page.getByRole('button', { name: 'Save Query' }).click();

    const successMessage = await page.getByText('Query saved successfully');
    await expect(successMessage).toBeVisible();
  });

  test('should display saved search query in saved queries list', async ({ page }) => {
    await page.getByRole('button', { name: 'Saved Queries' }).click();

    const savedQuery = await page.getByText('Test Query');
    await expect(savedQuery).toBeVisible();
  });
});
